var RCT=[['ann','Forfaits annuels','Formules à l’année et baby poney',function(m){return /f1|f2|f4/.test(m.forfait)}],['fc','Forfaits, cartes et demi-pensions','Toutes les formules de cours',function(m){return m.forfait!=='f5'}],['all','Tous les adhérents','Propriétaires compris',function(){return true}]];
