D.walkins=D.walkins||[
 {id:'wk1',first:'Chloé',last:'Vasseur',age:12,c:'c5',level:'Galop 3',what:'Balade d’une heure',price:35,lic:true,method:'Carte',at:'9 h 05'},
 {id:'wk2',first:'Antoine',last:'Lemaire',age:41,c:'c4',level:'Débutant',what:'Séance découverte',price:32,lic:true,method:'Espèces',at:'8 h 50'}];
var WACT=[['Séance découverte',32],['Balade d’une heure',35],['Baptême poney',12],['Cours particulier',45]],LICV=10;
function walkRows(){return D.walkins.map(function(w){return '<div class="cla-in" data-wk="'+w.id+'">'+ini(w.first,w.last,w.c)+'<div style="min-width:0"><div class="b s ellip">'+w.first+' '+w.last+' <span class="mut" style="font-weight:500">· '+w.age+' ans</span></div><div class="xs mut ellip">'+w.what+' · '+w.level+' · arrivé'+(MALE.test(w.first)?'':'e')+' à '+w.at+'</div></div><span class="hrow" style="--g:4px">'+U.chip('Décharge','ok',true)+'</span></div>'}).join('')}
function walkCard(){return '<div class="card" style="display:flex;flex-direction:column"><div class="ch"><div><h3>Cavaliers de passage</h3><div class="xs mut">Aujourd’hui, sans adhésion annuelle</div></div><span class="chip">'+D.walkins.length+'</span></div><div style="padding:6px 0">'+walkRows()+'</div><div class="cf" style="margin-top:auto"><span class="xs mut grow">Décharge signée sur la tablette, licence vacances, paiement à la séance</span><button class="btn sm pri" data-a="walk">'+ICON('plus','sm')+'Ajouter un cavalier de passage</button></div></div>'}
function sheetWalkin(after){var w={first:'',last:'',age:'',level:'Débutant',act:0,lic:true,method:'Carte',signed:false,phone:''},step=1;
  var sh=P.sheet({title:'Cavalier de passage',icon:'user',body:function(){draw()},foot:'<span data-foot style="display:contents"></span>'});
  function tot(){return WACT[w.act][1]+(w.lic?LICV:0)}
  function draw(){var b=$('.sb',sh),ft=$('[data-foot]',sh),bar='<div class="cla-steps">'+['Fiche','Décharge','Licence','Paiement'].map(function(s,i){return '<span class="'+(i+1<step?'done':i+1===step?'on':'')+'"><i>'+(i+1<step?ICON('check','sm'):i+1)+'</i>'+s+'</span>'}).join('')+'</div>';
    if(step===1){b.innerHTML=bar+'<div class="stack" style="--g:12px"><div class="g2" style="--g:10px"><div class="field"><span>Prénom</span><input class="in" data-w="first" value="'+E(w.first)+'" placeholder="Prénom"></div><div class="field"><span>Nom</span><input class="in" data-w="last" value="'+E(w.last)+'" placeholder="Nom"></div></div>'+
       '<div class="g2" style="--g:10px"><div class="field"><span>Âge</span><input class="in num" data-w="age" value="'+E(w.age)+'" inputmode="numeric" placeholder="Ans"></div><div class="field"><span>Niveau</span><select class="in" data-w="level">'+['Débutant','Galop 1 ou 2','Galop 3','Galop 4 et plus'].map(function(l){return '<option'+(l===w.level?' selected':'')+'>'+l+'</option>'}).join('')+'</select></div></div>'+
       '<div class="field"><span>Téléphone, ou celui du parent</span><input class="in" data-w="phone" value="'+E(w.phone)+'" placeholder="06 00 00 00 00" inputmode="tel"></div>'+
       '<div class="field"><span>Activité</span><div class="stack" style="--g:8px">'+WACT.map(function(a,i){return '<button class="cl-opt" data-manual data-act="'+i+'" aria-pressed="'+(i===w.act)+'"><div class="grow"><b class="s">'+a[0]+'</b></div><b class="num s">'+F.eur(a[1])+'</b></button>'}).join('')+'</div></div></div>';
      ft.innerHTML='<button class="btn pri" data-nx>Continuer'+ICON('right','sm')+'</button>'}
    else if(step===2){var minor=(+w.age||18)<18;b.innerHTML=bar+'<div class="clc-paper" style="padding:16px 18px"><h4>Décharge de responsabilité</h4><p>Je soussigné'+(minor?', responsable légal de '+E(w.first):'')+', '+(minor?'':E(w.first+' '+w.last)+', ')+'déclare avoir pris connaissance des risques liés à la pratique de l’équitation et m’engage à respecter les consignes de sécurité du club. Le port du casque est obligatoire. Je certifie ne connaître aucune contre-indication à la pratique.</p></div><div class="card flat" style="padding:16px;margin-top:14px"><b class="s">Signature sur la tablette</b><div class="xs mut" style="margin:2px 0 12px">Tendez la tablette à '+(minor?'son parent':E(w.first||'la personne'))+'.</div><div data-pad></div></div>';
      sigPad($('[data-pad]',b),{saved:false,hint:'Signez ici',done:function(){w.signed=true;var n=$('[data-nx]',sh);if(n)n.disabled=false;P.toast('Décharge signée et horodatée',{icon:'sign'})}});
      ft.innerHTML='<button class="btn" data-bk>'+ICON('back','sm')+'Retour</button><button class="btn pri" data-nx'+(w.signed?'':' disabled')+'>Continuer'+ICON('right','sm')+'</button>'}
    else if(step===3){b.innerHTML=bar+'<div class="stack" style="--g:12px"><div class="card flat list"><div class="li">'+sq('acc','shield','sm')+'<div class="grow"><div class="t">Licence vacances FFE</div><div class="s">Valable 30 jours, assurance en responsabilité civile comprise. Transmise à la fédération avec le prochain lot.</div></div><b class="num s">'+F.eur(LICV)+'</b><button class="tog" data-manual data-lic role="switch" aria-checked="'+w.lic+'" aria-label="Prendre la licence vacances"></button></div></div>'+
       (w.lic?'':'<div class="note warn">'+ICON('alert','sm')+'<span>Sans licence, le cavalier doit présenter une licence FFE 2027 en cours de validité.</span></div>')+'</div>';
      ft.innerHTML='<button class="btn" data-bk>'+ICON('back','sm')+'Retour</button><button class="btn pri" data-nx>Continuer'+ICON('right','sm')+'</button>'}
    else{b.innerHTML=bar+'<div class="card flat" style="padding:4px 14px">'+fact(WACT[w.act][0],F.eur(WACT[w.act][1]))+(w.lic?fact('Licence vacances FFE',F.eur(LICV)):'')+fact('<span style="color:var(--ink);font-weight:600">Total à la séance</span>','<span class="l num">'+F.eur(tot())+'</span>')+'</div><div class="cl-sub">Moyen de paiement</div><div class="stack" style="--g:8px">'+[['Carte','Terminal de l’accueil','card'],['Espèces','Inscrit au journal de caisse','wallet'],['Chèques-vacances','ANCV papier ou Connect','ticket']].map(function(o){return '<button class="cl-opt" data-manual data-pm="'+o[0]+'" aria-pressed="'+(o[0]===w.method)+'">'+sq('acc',o[2])+'<div class="grow"><b class="s">'+o[0]+'</b><div class="xs mut">'+o[1]+'</div></div></button>'}).join('')+'</div>';
      ft.innerHTML='<button class="btn" data-bk>'+ICON('back','sm')+'Retour</button><button class="btn pri" data-pay>'+ICON('card','sm')+'Encaisser '+F.eur(tot())+'</button>'}
    P.animate(b)}
  sh.addEventListener('input',function(e){var k=e.target.getAttribute('data-w');if(k)w[k]=e.target.value});
  on(sh,'[data-act]',function(b){w.act=+b.getAttribute('data-act');$$('[data-act]',sh).forEach(function(x){x.setAttribute('aria-pressed',x===b)})});
  on(sh,'[data-lic]',function(){w.lic=!w.lic;draw()});
  on(sh,'[data-pm]',function(b){w.method=b.getAttribute('data-pm');$$('[data-pm]',sh).forEach(function(x){x.setAttribute('aria-pressed',x===b)})});
  on(sh,'[data-bk]',function(){step--;draw()});
  on(sh,'[data-nx]',function(b){if(b.disabled)return;if(step===1&&!w.first.trim()){var i=$('[data-w="first"]',sh);i.focus();P.toast('Indiquez au moins le prénom',{icon:'info'});return}step++;draw()});
  on(sh,'[data-pay]',function(b){b.disabled=true;b.innerHTML='<span class="cl-spin"></span>';setTimeout(function(){var first=w.first.trim(),last=w.last.trim()||'',nw={id:'wk'+Date.now(),first:first,last:last,age:+w.age||18,c:'c'+(1+D.walkins.length%7),level:w.level,what:WACT[w.act][0],price:WACT[w.act][1],lic:w.lic,method:w.method,at:'9 h 41'};D.walkins.unshift(nw);sh.close();after();
    P.toast(E(first)+' est enregistré'+(MALE.test(first)?'':'e')+' : décharge signée, '+F.eur(tot())+' encaissés'+(w.lic?', licence vacances prise':''),{icon:'checkc',undo:function(){D.walkins=D.walkins.filter(function(x){return x!==nw});after()}})},P.RM?60:900)});
  return sh}
