function sheetGalop(m,after){var g=m.galop+1,res='ok';
  var sh=P.sheet({title:'Valider le Galop '+g+' de '+m.first,icon:'medal',body:function(b){b.innerHTML='<div data-z><div class="g2" style="--g:10px"><div class="field"><span>Date de l’examen</span><input class="in" value="17/11/2026"></div><div class="field"><span>Examinateur</span><select class="in" data-ex>'+['s04','s02','s03'].map(function(id){var s=D.staffer(id);return '<option value="'+id+'">'+s.first+' '+s.last+' · '+s.dip+'</option>'}).join('')+'</select></div></div>'+
    '<div class="cl-sub">Compétences évaluées</div><div class="card flat list">'+SKILLS.map(function(s){return '<div class="li"><div class="grow"><div class="t">'+s[0]+'</div><div class="s">'+pl(s[1].length,'compétence')+' du programme fédéral</div></div>'+U.chip('Acquis','ok',true)+'</div>'}).join('')+'</div>'+
    '<div class="field" style="margin-top:14px"><span>Résultat</span>'+U.seg([['ok','Admis'+fe(m)],['ko','À retravailler']],'ok','data-res')+'</div>'+
    (licOK(m)?'<div class="note" style="margin-top:14px">'+ICON('shield','sm')+'<span>Licence 2027 n° '+m.lic+' valide. Le galop est inscrit sur la licence et le diplôme apparaît dans l’espace FFE du cavalier.</span></div>':'<div class="note warn" style="margin-top:14px">'+ICON('alert','sm')+'<span>La licence 2027 de '+m.first+' n’est pas encore prise : la FFE n’enregistre pas un galop sans licence en cours.</span></div>')+'</div>'},
   foot:licOK(m)?'<button class="btn ghost" data-x2>Annuler</button><button class="btn pri" data-ok>'+ICON('upload','sm')+'<span class="cl-ll">Valider et transmettre à la FFE</span><span class="cl-ls">Transmettre à la FFE</span></button>':'<button class="btn ghost" data-x2>Annuler</button><button class="btn pri" data-lic>'+ICON('shield','sm')+'Prendre la licence d’abord</button>'});
  on(sh,'[data-res]',function(b){res=b.getAttribute('data-res');var ok=$('[data-ok]',sh);if(ok)ok.innerHTML=res==='ok'?ICON('upload','sm')+'<span class="cl-ll">Valider et transmettre à la FFE</span><span class="cl-ls">Transmettre à la FFE</span>':ICON('check','sm')+'Enregistrer le bilan'});
  $('[data-x2]',sh).onclick=sh.close;var lb=$('[data-lic]',sh);if(lb)lb.onclick=function(){sheetLicences([m.id])};
  var ok=$('[data-ok]',sh);if(ok)ok.onclick=function(){var es=D.staffer($('[data-ex]',sh).value);
    if(res!=='ok'){sh.close();P.toast('Bilan enregistré : '+m.first+' repassera le Galop '+g+' au prochain examen',{icon:'checkc'});return}
    var ST=[['Dossier contrôlé','Licence 2027 valide, examinateur diplômé : '+es.first+' '+es.last],['Transmis à la FFE','Via la solution agréée, connexion chiffrée'],['Galop '+g+' inscrit sur la licence','Diplôme disponible en PDF dans l’espace de '+m.first]];
    var z=$('[data-z]',sh);z.innerHTML='<div class="card flat" style="padding:6px 16px">'+ST.map(function(s,i){return '<div class="cl-step wait" data-s="'+i+'"><span class="ic">'+ICON('dot')+'</span><div><b class="s">'+s[0]+'</b><div class="xs mut">'+s[1]+'</div></div></div>'}).join('')+'</div><div data-res2></div>';
    $('.sf',sh).style.display='none';var i=0;(function next(){var el=$('[data-s="'+i+'"]',z);if(i>0){var pv=$('[data-s="'+(i-1)+'"]',z);pv.className='cl-step done';$('.ic',pv).innerHTML=ICON('checkc')}
      if(!el){m.galop=g;$('[data-res2]',z).innerHTML='<div class="clf-gok pop"><span class="strass"></span><div><b>Galop '+g+' validé</b><div class="s mut">'+m.first+' le retrouve sur sa licence et dans son espace. Examinateur : '+es.first+' '+es.last+'.</div></div></div><div class="hrow" style="margin-top:14px;justify-content:flex-end"><button class="btn" data-dip>'+ICON('download','sm')+'Diplôme en PDF</button><button class="btn pri" data-end>Terminer</button></div>';
        $('[data-dip]',z).onclick=function(){P.toast('Diplôme du Galop '+g+' téléchargé',{icon:'download'})};$('[data-end]',z).onclick=function(){sh.close();after();P.toast('Galop '+g+' de '+m.first+' validé et transmis à la FFE',{icon:'medal'})};return}
      el.className='cl-step';$('.ic',el).innerHTML='<span class="cl-spin"></span>';i++;setTimeout(next,P.RM?60:850)})()};return sh}

