    if(b=t.closest('[data-day]')){var k=+b.getAttribute('data-day'),dp=D.halfboard.filter(function(d){return d.id===PS.dp})[0],c=calCells(dp)[k],nx={o:'r',r:'z',z:'o',k:'o'}[c.who];PS.cal[dp.id+k]=nx;body();var nb=$('[data-day="'+k+'"]',el);if(nb)nb.classList.add('flip');
      P.toast(F.dateL(c.d).replace(/^./,function(z){return z.toUpperCase()})+' : '+(nx==='z'?'jour de repos':nx==='r'?'attribué à '+D.member(dp.rider).first:'attribué à '+D.member(D.horse(dp.horse).owner).first)+'. Les deux cavaliers sont prévenus.',{icon:'calendar_add',undo:function(){PS.cal[dp.id+k]=c.who;body()}});return}
