P.css(`
.clb-st{display:flex;flex-direction:column;gap:12px;padding:16px;cursor:pointer;text-align:left;transition:box-shadow var(--t-2),transform var(--t-2) var(--e-out)}
.clb-st:hover{transform:translateY(-2px);box-shadow:inset 0 0 0 1px var(--line-2),var(--shadow-2)}
.clb-dt{width:54px;border-radius:12px;background:var(--acc-pale);color:var(--acc);text-align:center;padding:7px 0 6px;flex:none;font:700 19px/1 var(--f-display);letter-spacing:-.03em}
.clb-dt small{display:block;font:600 10.5px var(--f-text);letter-spacing:.06em;text-transform:uppercase;margin-top:3px}
.clb-add{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-height:170px;border-radius:var(--r-lg);box-shadow:inset 0 0 0 1.5px var(--line-2);color:var(--mut);text-align:center;cursor:pointer;transition:background var(--t-2);padding:16px}
.clb-add:hover{background:var(--surface)}
.clb-sum{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0}
.clb-sum>div{padding:14px 18px}
.clb-sum>div+div{border-left:1px solid var(--line)}
.clb-sum b{display:block;font:700 24px/1.1 var(--f-display);letter-spacing:-.03em;font-variant-numeric:tabular-nums}
.clb-gc{position:relative;border-radius:18px;background:var(--navy);color:var(--navy-ink);padding:20px 22px;aspect-ratio:1.62/1;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;box-shadow:var(--shadow-2);max-width:380px;width:100%}
.clb-gc::after{content:"";position:absolute;right:-70px;top:-70px;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--strass) 45%,transparent),transparent 66%);pointer-events:none}
.clb-gc .amt{font:700 44px/1 var(--f-display);letter-spacing:-.04em;font-variant-numeric:tabular-nums}
.clb-gc .code{font:500 12px var(--f-mono);letter-spacing:.08em;opacity:.75}
.clb-gc .strass{background:var(--strass);width:14px;height:14px}
.clb-pos{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(320px,1fr);gap:14px;align-items:start}
.clb-tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.clb-tile{display:flex;flex-direction:column;justify-content:space-between;gap:10px;min-height:86px;padding:12px;border-radius:var(--r-md);background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);text-align:left;transition:transform var(--t-1) var(--e-out),box-shadow var(--t-2),background var(--t-2);position:relative}
.clb-tile:hover{box-shadow:inset 0 0 0 1px var(--line-2);background:var(--surface-2)}
.clb-tile:active{transform:scale(.96)}
.clb-tile b{font-size:13px;font-weight:600;line-height:1.25;padding-right:24px}
.clb-tile span{font-size:13px;color:var(--mut);font-variant-numeric:tabular-nums}
.clb-tile em{position:absolute;top:8px;right:8px;min-width:20px;height:20px;padding:0 6px;border-radius:10px;background:var(--acc);color:var(--acc-ink);font:700 11px var(--f-text);display:grid;place-items:center;animation:pop var(--t-3) var(--e-spring) both}
.clb-tk{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:10px;align-items:center;padding:9px 16px}
.clb-tk+.clb-tk{border-top:1px solid var(--line)}
.clb-pm{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.clb-pm button{height:44px;border-radius:10px;font-size:12.5px;font-weight:600;box-shadow:inset 0 0 0 1px var(--line-2);display:flex;align-items:center;justify-content:center;gap:6px;color:var(--ink-2);transition:all var(--t-2)}
.clb-pm button[aria-pressed="true"]{background:var(--navy);color:var(--navy-ink);box-shadow:none}
.clb-tpe{width:190px;margin:8px auto 0;border-radius:26px;background:var(--navy);padding:14px 14px 22px;box-shadow:var(--shadow-3);display:flex;flex-direction:column;gap:14px;align-items:center}
.clb-tpe .scr{width:100%;border-radius:14px;background:var(--surface);color:var(--ink);padding:16px 10px;text-align:center;min-height:128px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px}
.clb-tpe .scr b{font:700 24px/1 var(--f-display);letter-spacing:-.03em}
.clb-tpe .keys{display:grid;grid-template-columns:repeat(3,22px);gap:7px}
.clb-tpe .keys i{height:9px;border-radius:3px;background:color-mix(in srgb,var(--navy-ink) 22%,transparent)}
.clb-wav{position:relative;width:38px;height:22px;overflow:hidden;margin-top:4px}
.clb-wav i{position:absolute;left:50%;top:0;border:2px solid var(--acc);border-color:var(--acc) transparent transparent transparent;border-radius:50%;transform:translateX(-50%);opacity:.2;animation:clbwav 1.2s var(--e-in-out) infinite}
.clb-wav i:nth-child(1){width:12px;height:12px;top:14px}.clb-wav i:nth-child(2){width:24px;height:24px;top:7px;animation-delay:.15s}.clb-wav i:nth-child(3){width:36px;height:36px;animation-delay:.3s}
@keyframes clbwav{50%{opacity:1}}
.clb-ok{width:46px;height:46px;border-radius:50%;background:var(--ok);display:grid;place-items:center;animation:pop var(--t-3) var(--e-spring) both}
.clb-ok svg{width:24px;height:24px;fill:none;stroke:var(--surface);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:24;stroke-dashoffset:24;animation:clbdraw 320ms var(--e-out) 160ms forwards}
@keyframes clbdraw{to{stroke-dashoffset:0}}
.clb-web{border-radius:var(--r-lg);overflow:hidden;box-shadow:inset 0 0 0 1px var(--line),var(--shadow-2);background:var(--surface)}
.clb-web .bar2{display:flex;align-items:center;gap:6px;padding:9px 12px;background:var(--bg-2);border-bottom:1px solid var(--line)}
.clb-web .bar2 i{width:9px;height:9px;border-radius:50%;background:var(--line-2)}
.clb-web .bar2 span{flex:1;margin-left:8px;height:24px;border-radius:7px;background:var(--surface);font:500 11.5px var(--f-mono);color:var(--mut);display:flex;align-items:center;gap:6px;padding:0 10px;min-width:0;white-space:nowrap;overflow:hidden}
.clb-web .hero{background:var(--navy);color:var(--navy-ink);padding:26px 24px;position:relative;overflow:hidden}
.clb-web .hero h4{color:var(--navy-ink);font-size:24px;letter-spacing:-.03em}
.clb-web .sec{padding:18px 24px;border-top:1px solid var(--line);animation:fade var(--t-3) var(--e-out) both}
.clb-web .sec h5{font:700 14px var(--f-display);letter-spacing:-.01em;margin:0 0 10px}
.clb-web .it{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:12px;box-shadow:inset 0 0 0 1px var(--line);font-size:13px}
.clb-qr{width:96px;height:96px;color:var(--ink);background:var(--surface);border-radius:10px;padding:8px;box-shadow:inset 0 0 0 1px var(--line);flex:none}
.clb-paybar{display:none}
@container main (max-width:1080px){.clb-tiles{grid-template-columns:repeat(3,minmax(0,1fr))}.clb-pos{grid-template-columns:minmax(0,1.2fr) minmax(300px,1fr)}}
@container main (max-width:760px){.clb-pos{grid-template-columns:minmax(0,1fr)}.clb-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.clb-tile{min-height:76px}
 .clb-paybar{display:flex;position:sticky;bottom:8px;z-index:4;margin-top:12px;align-items:center;gap:12px;padding:8px 8px 8px 16px;border-radius:16px;background:var(--navy);color:var(--navy-ink);box-shadow:var(--shadow-3)}
 .clb-sum>div{padding:12px}.clb-sum b{font-size:19px}.clb-web .hero,.clb-web .sec{padding-left:16px;padding-right:16px}}
`);
var BS={tab:'stages',cat:'Favoris',cart:{p09:1,p11:2,p14:1},client:'',method:'Carte',pub:{st:1,ev:1,gc:1,es:1,dp:0,av:1},gc:50,scat:'Tout',sales:null};
function item(id){return D.shopItems.filter(function(p){return p.id===id})[0]}
function cartLines(){return Object.keys(BS.cart).filter(function(k){return BS.cart[k]>0}).map(function(k){return {p:item(k),q:BS.cart[k]}})}
function cartTot(){return sum(cartLines(),function(l){return l.p.price*l.q})}
function e2(v){return F.eur(v,v%1!==0)}
function campList(c){return D.members.filter(function(m){return m.forfait!=='f5'&&m.age<19}).sort(function(a,b){return R(a.id,c.id,999)-R(b.id,c.id,999)}).slice(0,c.taken)}
function qr(seed){var n=21,s='',f=function(x,y){var inF=function(ox,oy){var a=x-ox,b=y-oy;return a>=0&&a<7&&b>=0&&b<7?((a===0||a===6||b===0||b===6||(a>1&&a<5&&b>1&&b<5))?1:0):-1},v=inF(0,0);if(v<0)v=inF(14,0);if(v<0)v=inF(0,14);if(v>=0)return v;if((x<8&&y<8)||(x>12&&y<8)||(x<8&&y>12))return 0;return R(seed,x+'.'+y,100)<48};
  for(var y=0;y<n;y++)for(var x=0;x<n;x++)if(f(x,y))s+='<rect x="'+x+'" y="'+y+'" width="1.02" height="1.02"/>';return '<svg class="clb-qr" viewBox="0 0 21 21" fill="currentColor" role="img" aria-label="QR code de la page publique">'+s+'</svg>'}

function sheetCamp(c){var L=campList(c),co=D.staffer(c.coach),rev=c.taken*c.price;
  var sh=P.sheet({title:c.title,icon:'holiday',wide:true,body:'<div class="hrow wrap" style="--g:6px;margin-bottom:14px"><span class="chip lg">Du '+F.date(c.from)+' au '+F.dateY(c.to)+'</span><span class="chip lg">'+c.hours+'</span><span class="chip lg">'+c.level+'</span>'+(c.online?'<span class="chip acc dot lg">En vente en ligne</span>':'<span class="chip line lg">Brouillon</span>')+'</div>'+
   '<div class="g2" style="--g:14px"><div class="card flat" style="padding:4px 14px">'+fact('Encadrement',co.first+' '+co.last)+fact('Tarif adhérent',F.eur(c.price))+fact('Tarif extérieur',F.eur(c.price+30)+', licence vacances comprise')+fact('À la journée',F.eur(c.day))+fact('Options',c.opts)+'</div>'+
   '<div class="card flat pad stack" style="--g:10px;padding:14px"><div class="hrow sp"><b>'+c.taken+' inscrits sur '+c.cap+'</b><b class="num">'+F.eur(rev)+'</b></div>'+U.bar(c.taken/c.cap*100,c.taken>=c.cap?'var(--warn)':'')+'<div class="xs mut">'+(c.wait?pl(c.wait,'cavalier')+' en liste d’attente. La place se propose seule si un inscrit annule.':(c.cap-c.taken)+' places restantes. Acompte de 30 % à la réservation, solde 7 jours avant.')+'</div><div class="hrow sp" style="margin-top:4px"><span class="s b">Vente en ligne</span>'+U.tog(c.online)+'</div><div class="hrow sp"><span class="s b">Chèques-vacances et Pass’Sport acceptés</span>'+U.tog(true)+'</div></div></div>'+
   '<div class="cl-sub">Inscrits</div><div class="card flat list">'+L.map(function(m,i){var paid=R(m.id,c.id+'p',10);return '<div class="li click" data-go="adherent" data-id="'+m.id+'">'+U.av(m,'sm')+'<div class="grow"><div class="t">'+nm(m)+'</div><div class="s">'+m.age+' ans · '+(m.galop?'Galop '+m.galop:'Débutant')+(i%4===1?' · repas du midi':'')+'</div></div><div class="r">'+(paid<6?U.chip('Payé','ok',true):paid<9?U.chip('Acompte','acc',true):U.chip('À régler','warn',true))+'</div></div>'}).join('')+'</div>',
   foot:'<button class="btn" data-f="sheet">'+ICON('doc','sm')+'Feuille d’émargement</button><button class="btn" data-f="msg">'+ICON('chat','sm')+'Écrire aux inscrits</button><button class="btn pri" data-f="add">'+ICON('plus','sm')+'Inscrire un cavalier</button>'});
  on(sh,'[data-f]',function(b){var a=b.getAttribute('data-f');if(a==='sheet')P.toast('Feuille d’émargement téléchargée, '+c.taken+' cavaliers',{icon:'download'});else if(a==='msg')sheetMessage(L.map(function(m){return m.id}),'Bonjour {prénom},\n\nQuelques informations pratiques avant le stage « '+c.title+' » : rendez-vous à 9 h 45 au club-house, avec casque, bottes et gants.\n\n');
    else if(c.taken>=c.cap){c.wait++;sh.close();P.rerender();P.toast('Stage complet : cavalier ajouté à la liste d’attente',{icon:'waitlist'})}else{c.taken++;sh.close();P.rerender();P.toast('Cavalier inscrit, lien de paiement de l’acompte envoyé',{icon:'checkc',undo:function(){c.taken--;P.rerender()}})}})}
