P.brain.push(
 {role:'gerant',re:/licen|ffe|certificat|questionnaire/i,reply:function(){var l=D.members.filter(function(m){return !licOK(m)}),ok=l.filter(function(m){return m.cert});if(!l.length)return {text:'Les '+D.members.length+' licences 2027 sont enregistrées. Rien à transmettre à la fédération.'};
   return {text:l.length+' adhérents n’ont pas encore leur licence 2027. '+ok.length+' dossiers sont complets et peuvent partir en lot, '+(l.length-ok.length)+' attendent une pièce de santé.',card:l.slice(0,4).map(function(m){return '<div class="hrow sp"><span class="s">'+nm(m)+'</span>'+(m.cert?U.chip('Prêt','ok'):U.chip('Santé à fournir','warn'))+'</div>'}).join(''),
    actions:[{label:'Préparer le lot de '+ok.length,run:function(){P.go('adherents');setTimeout(function(){sheetLicences()},80);return 'Lot ouvert'}},{label:'Voir ces adhérents',run:function(){AS.seg='lic';P.go('adherents');return 'Segment affiché'}}]}}},
 {role:'gerant',re:/demi.?pension|candidat|mise en relation/i,reply:function(){var o=D.halfboardOffers[1],A=applicants(o),b=A[0];return {text:D.halfboard.length+' demi-pensions sont en cours pour '+F.eur(sum(D.halfboard,function(d){return d.price}))+' par mois, et '+D.halfboardOffers.length+' annonces sont en ligne. Pour '+D.horse(o.horse).name+', le meilleur accord est '+nm(b.m)+' : Galop '+b.m.galop+', '+b.days.join(' et ')+', budget de '+b.budget+' €.',
    card:A.slice(0,3).map(function(a){return '<div class="hrow sp"><span class="s">'+nm(a.m)+'</span><b class="s num">'+a.score+' %</b></div>'}).join(''),
    actions:[{label:'Proposer un essai à '+b.m.first,run:function(){PS.trial[o.id+b.m.id]=1;P.toast('Essai proposé à '+b.m.first+' : samedi 21 novembre à 14 h');return 'Essai proposé'}},{label:'Voir les candidats',run:function(){PS.tab='match';P.go('pensions',{offer:o.id});return 'Ouvert'}}]}}},
 {role:'gerant',re:/contrat|signature|signer|sign[ée]/i,reply:function(){var p=D.contracts.filter(function(c){return c.status==='à signer'});if(!p.length)return {text:'Tous les contrats sont signés et archivés.'};
   return {text:pl(p.length,'contrat attend','contrats attendent')+' une signature. Le plus ancien a été envoyé '+F.rel(p[p.length-1].date)+'.',card:p.map(function(c){return '<div class="hrow sp"><span class="s ellip">'+c.title+'</span><span class="xs mut" style="flex:none">'+cPend(c).map(function(s){return s.id==='s01'?'vous':s.name.split(' ')[0]}).join(', ')+'</span></div>'}).join(''),
    actions:[{label:'Relancer les signataires',run:function(){P.toast('Relances envoyées par e-mail et SMS',{icon:'send'});return 'Relances envoyées'}},{label:'Ouvrir les contrats',run:function(){CS.f='à signer';P.go('contrats');return 'Ouvert'}}]}}},
 {role:'gerant',re:/pension|box libre|liste d.attente/i,reply:function(){var H=ownersH();return {text:H.length+' chevaux sont en pension. Novembre représente '+F.eur(sum(H,pTot))+', dont '+F.eur(sum(H,function(h){return xTot(pens(h))}))+' de prestations à la carte. '+pl(freeBoxes(),'box est libre','boxes sont libres')+' et '+D.boxWait.length+' demandes attendent.',actions:[{label:'Facturer novembre',run:function(){PS.tab='pens';P.go('pensions');setTimeout(sheetBill,80);return 'Facturation ouverte'}},{label:'Voir la liste d’attente',run:function(){PS.tab='wait';P.go('pensions');return 'Ouvert'}}]}}},
 {role:'gerant',re:/stage|anniversaire|boutique|caisse|carte cadeau/i,reply:function(){var c=D.camps;return {text:sum(c,function(x){return x.taken})+' cavaliers sont inscrits aux '+c.length+' stages. « '+c[1].title+' » est complet avec '+c[1].wait+' cavaliers en attente, « '+c[4].title+' » n’est pas encore en vente.',card:c.slice(0,4).map(function(x){return '<div class="hrow sp"><span class="s ellip">'+x.title+'</span><b class="s num" style="flex:none">'+x.taken+' / '+x.cap+'</b></div>'}).join(''),actions:[{label:'Voir les stages',run:function(){P.go('boutique',{tab:'stages'});return 'Ouvert'}},{label:'Ouvrir la caisse',run:function(){P.go('boutique',{tab:'pos'});return 'Caisse ouverte'}}]}}});
